package com.yeyamo_mobile.api.feed_service.infrastructure.outbox;import java.time.Instant;import java.util.concurrent.TimeUnit;import org.slf4j.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component@ConditionalOnProperty(name="feed.outbox.enabled",havingValue="true",matchIfMissing=true)public class FeedOutboxPublisher{private static final Logger log=LoggerFactory.getLogger(FeedOutboxPublisher.class);private final FeedOutboxRepository repo;private final KafkaTemplate<String,String>kafka;private final String topic;public FeedOutboxPublisher(FeedOutboxRepository r,KafkaTemplate<String,String>k,@Value("${yeyamo.kafka.topics.feed-events:feed.events}")String t){repo=r;kafka=k;topic=t;}@Scheduled(fixedDelayString="${feed.outbox.delay-ms:1000}")@Transactional public void publish(){for(var e:repo.findTop100ByPublishedAtIsNullOrderByOccurredAtAsc()){try{kafka.send(topic,e.getAggregateId(),e.getPayload()).get(5,TimeUnit.SECONDS);e.setPublishedAt(Instant.now());e.setLastError(null);}catch(Exception x){e.setAttempts(e.getAttempts()+1);String m=x.getMessage()==null?"Kafka failure":x.getMessage();e.setLastError(m.substring(0,Math.min(1000,m.length())));log.warn("Feed outbox event {} failed",e.getId());}repo.save(e);}}}
